from pathlib import Path
import difflib,hashlib,json
root=Path('/workspace/共享/Eliora/未来教室计划')
out=Path('/tmp/fc-round31-device-evidence/round31-plan-draft');out.mkdir(parents=True,exist_ok=True)
changes=[]
def propose(name, transform):
 p=root/name; raw=p.read_bytes();old=raw.decode();new=transform(old);assert new!=old
 patch=''.join(difflib.unified_diff(old.splitlines(keepends=True),new.splitlines(keepends=True),fromfile='a/'+name,tofile='b/'+name))
 changes.append({'path':name,'beforeBytes':len(raw),'beforeSha256':hashlib.sha256(raw).hexdigest(),'proposedBytes':len(new.encode()),'proposedSha256':hashlib.sha256(new.encode()).hexdigest(),'patch':patch})
def once(s,old,new):assert s.count(old)==1,(old,s.count(old));return s.replace(old,new,1)
